-- Trino tạo collection MongoDB web_notes (và ghi lược đồ vào _schema). Connector MongoDB hỗ trợ INSERT/DELETE,
-- không hỗ trợ UPDATE – sửa document trong mongo-express (http://localhost:8083).
-- Xóa thử: DELETE FROM mongodb.joblens.web_notes WHERE note_id = 'n2'
CREATE TABLE IF NOT EXISTS mongodb.joblens.web_notes (note_id varchar, location_code varchar, content varchar);
INSERT INTO mongodb.joblens.web_notes VALUES ('n1', '01', 'Ghi chú thử từ SQLPad'), ('n2', '79', 'Ghi chú thứ hai');
SELECT n.note_id, d.name AS tinh_thanh, n.content
FROM mongodb.joblens.web_notes n JOIN iceberg.gold.dim_location d ON d.location_code = n.location_code
ORDER BY n.note_id;
